<#
.SYNOPSIS
    BATCH: runs multiple Windows shellcodes through the same native
    loader + single shared Procmon capture, one after another, and
    reports what was observed per file. Built on the same loader/logic
    already proven working in run_all.ps1 (single-file version) -- see
    that file's module docstring for the full history of what was fixed
    to get here (exit-code sync, Procmon startup race, PID-based
    filtering, explicit exit 0).

    UNLIKE run_all.ps1, this does NOT compute a pass/fail verdict per
    file -- manifest.json has no `category` field per Windows record
    (only the 3 hand-picked GROUND_TRUTH samples in run_all.ps1 have
    one), so there is nothing to check observed behaviour AGAINST here.
    This reports RAW OBSERVED EVENTS per file instead, same principle as
    scripts/survey_windows.py's Speakeasy-based recon pass, but backed
    by REAL execution instead of emulation. A human (or a later
    categorisation pass) turns this into verdicts.

.NOTES
    UNTESTED -- built by extending the now-proven single-file pipeline,
    but the BATCH-specific parts (one shared Procmon session across many
    runs, splitting one CSV by per-file PID afterward) have never been
    run for real. Expect the first real run to surface something.

    Run from an ELEVATED PowerShell.

.EXAMPLE
    .\run_batch.ps1 -ManifestPath manifest.json -MaxFiles 10
#>

param(
    [Parameter(Mandatory=$true)][string]$ManifestPath,
    [ValidateSet("x86","x64")][string]$Arch = "x86",
    [int]$PerFileTimeoutSeconds = 8,
    [int]$MaxFiles = 0,           # 0 = no limit, test every matching record
    [string[]]$OnlyPaths = @(),   # optional: restrict to these manifest "path" values
    [string]$WorkDir = ""
)

$ErrorActionPreference = "Stop"
if ([string]::IsNullOrWhiteSpace($WorkDir)) {
    $WorkDir = Join-Path $env:TEMP ("shellcode_batch_" + (Get-Random))
}
New-Item -ItemType Directory -Force -Path $WorkDir | Out-Null
Write-Host "Working directory: $WorkDir"

# =====================================================================
# STEP 1: decode the embedded, pre-compiled loader (same binary as
# run_all.ps1 -- confirmed valid PE32/PE32+, and now confirmed WORKING
# end to end on real windows-latest runners, not just compiled).
# =====================================================================
Write-Host "[1/8] Decoding embedded loader ($Arch)"
$loaderExe = Join-Path $WorkDir "loader.exe"
if ($Arch -eq "x86") {
    $loaderB64 = ""
} else {
    $loaderB64 = ""
}
[System.IO.File]::WriteAllBytes($loaderExe, [System.Convert]::FromBase64String($loaderB64))

# =====================================================================
# STEP 2: load manifest.json, filter to Windows records with extracted
# bytes, apply -OnlyPaths / -MaxFiles if given
# =====================================================================
Write-Host "[2/8] Loading manifest: $ManifestPath"
$manifest = Get-Content -Raw -Path $ManifestPath | ConvertFrom-Json
$records = $manifest | Where-Object { $_.os -eq "windows" -and $_.supported -eq $true }
if ($OnlyPaths.Count -gt 0) {
    $records = $records | Where-Object { $OnlyPaths -contains $_.path }
}
if ($MaxFiles -gt 0) {
    $records = $records | Select-Object -First $MaxFiles
}
Write-Host "    $($records.Count) record(s) selected"

# =====================================================================
# STEP 3: auto-download Procmon if not already present next to this
# script (same logic as run_all.ps1)
# =====================================================================
$procmonExe = Join-Path $WorkDir "Procmon.exe"
$existingProcmon = Get-ChildItem -Path (Split-Path -Parent $MyInvocation.MyCommand.Path) -Filter "Procmon*.exe" -ErrorAction SilentlyContinue | Select-Object -First 1
if ($existingProcmon) {
    Write-Host "[3/8] Found existing $($existingProcmon.Name), using it"
    $procmonExe = $existingProcmon.FullName
} else {
    Write-Host "[3/8] Downloading Procmon from Microsoft/Sysinternals..."
    $zipPath = Join-Path $WorkDir "ProcessMonitor.zip"
    Invoke-WebRequest -Uri "https://download.sysinternals.com/files/ProcessMonitor.zip" -OutFile $zipPath
    Expand-Archive -Path $zipPath -DestinationPath $WorkDir -Force
    $procmonExe = Join-Path $WorkDir "Procmon.exe"
    if (-not (Test-Path $procmonExe)) {
        $procmonExe = Join-Path $WorkDir "Procmon64.exe"
    }
}

# =====================================================================
# STEP 4: block network for the loader -- BOTH directions this time,
# not just outbound. run_all.ps1 only needed outbound (its one
# ground-truth sample never listens for anything), but a real batch
# will include bind-shell / reverse-shell samples that could try to
# LISTEN for an inbound connection. Blocking only outbound would leave
# a real open port reachable from outside the runner for however long
# that sample runs -- inbound must be blocked too, unconditionally, not
# just for samples we've pre-identified as listeners.
# =====================================================================
Write-Host "[4/8] Blocking network (both directions) for loader.exe"
$ruleNameOut = "shellcode-batch-block-out-$(Get-Random)"
$ruleNameIn = "shellcode-batch-block-in-$(Get-Random)"
New-NetFirewallRule -DisplayName $ruleNameOut -Direction Outbound -Program $loaderExe -Action Block | Out-Null
New-NetFirewallRule -DisplayName $ruleNameIn -Direction Inbound -Program $loaderExe -Action Block | Out-Null

# =====================================================================
# STEP 5: start ONE shared Procmon capture for the whole batch -- NOT
# restarted per file. Confirmed in the single-file version that
# start/stop is the fragile part (needs a real settle delay, /Terminate
# sometimes needs a retry); doing that dance once per batch instead of
# once per file is both faster and avoids repeating the fragile part
# N times.
# =====================================================================
$pmlPath = Join-Path $WorkDir "batch_capture.pml"
Write-Host "[5/8] Starting shared Procmon capture -> $pmlPath"
if (Test-Path $pmlPath) { Remove-Item $pmlPath -Force }
Start-Process -FilePath $procmonExe -ArgumentList `
    "/AcceptEula /Quiet /Minimized /BackingFile `"$pmlPath`""
& $procmonExe /WaitForIdle | Out-Null
Start-Sleep -Seconds 3   # same settle delay proven necessary in run_all.ps1

# =====================================================================
# STEP 6: run each shellcode in turn, recording its PID and exit
# status. Procmon keeps capturing across all of them.
# =====================================================================
Write-Host "[6/8] Running $($records.Count) shellcode(s)..."
$runLog = @()
$i = 0
foreach ($rec in $records) {
    $i++
    Write-Host "  [$i/$($records.Count)] $($rec.path) ($($rec.length) bytes)"
    $bytes = [byte[]] -split ($rec.bytes -replace '..', '0x$0 ')
    $scFile = Join-Path $WorkDir "sc_$i.bin"
    [System.IO.File]::WriteAllBytes($scFile, $bytes)

    $proc = Start-Process -FilePath $loaderExe -ArgumentList "`"$scFile`"" -PassThru -NoNewWindow
    $finished = $proc.WaitForExit($PerFileTimeoutSeconds * 1000)
    if (-not $finished) {
        Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue
        $exitCode = "OUTER_TIMEOUT"
    } else {
        $proc.WaitForExit()  # sync exit state -- same fix as run_all.ps1
        $exitCode = "$($proc.ExitCode)"
    }

    $runLog += [PSCustomObject]@{
        Index = $i
        Path = $rec.path
        Pid_ = $proc.Id
        ExitCode = $exitCode
    }

    # Small gap between runs -- not proven necessary the way the
    # startup settle delay was, but cheap insurance against runs
    # blurring together in the shared capture given how fast some of
    # these exit (confirmed: under 200ms for at least one real sample).
    Start-Sleep -Milliseconds 500
}

# =====================================================================
# STEP 7: stop Procmon once, export ONE CSV for the whole batch
# =====================================================================
Write-Host "[7/8] Stopping Procmon and exporting CSV"
Start-Sleep -Seconds 2
& $procmonExe /Terminate
$waited = 0
while ((Get-Process -Name "Procmon","Procmon64" -ErrorAction SilentlyContinue)) {
    if ($waited -ge 15) {
        Write-Warning "Procmon still running after 15s -- retrying /Terminate once more"
        & $procmonExe /Terminate
    }
    if ($waited -ge 30) {
        Write-Warning "Procmon did not exit after 30s total -- capture may be incomplete"
        break
    }
    Start-Sleep -Seconds 1
    $waited++
}
$csvPath = Join-Path $WorkDir "batch_capture.csv"
& $procmonExe /OpenLog "$pmlPath" /SaveAs "$csvPath" /Quiet /AcceptEula

# /SaveAs, same as /Terminate earlier, does not block until the
# underlying work is actually done -- confirmed the hard way: a fixed
# Start-Sleep that was enough for the single-file version wasn't enough
# here (bigger combined CSV from 5 runs). Poll for the file to actually
# be openable instead of guessing a sleep duration -- same principle as
# the Procmon-process-exit poll loop above, applied to the file handle
# instead of the process.
function Wait-FileReady {
    param([string]$Path, [int]$TimeoutSeconds = 30)
    $waited = 0
    while ($waited -lt $TimeoutSeconds) {
        if (Test-Path $Path) {
            try {
                $stream = [System.IO.File]::Open($Path, 'Open', 'Read', 'None')
                $stream.Close()
                return $true
            } catch {
                # still locked by whatever background process /SaveAs spawned
            }
        }
        Start-Sleep -Seconds 1
        $waited++
    }
    return $false
}
if (-not (Wait-FileReady -Path $csvPath -TimeoutSeconds 30)) {
    Write-Warning "CSV file still locked/missing after 30s -- proceeding anyway, Import-Csv may fail"
}
Remove-NetFirewallRule -DisplayName $ruleNameOut -ErrorAction SilentlyContinue | Out-Null
Remove-NetFirewallRule -DisplayName $ruleNameIn -ErrorAction SilentlyContinue | Out-Null

if (-not (Test-Path $csvPath)) {
    Write-Error "CSV export failed -- $pmlPath may still be usable manually, check $WorkDir"
    exit 1
}

# =====================================================================
# STEP 8: parse the ONE combined CSV, split events per file by PID,
# print a per-file summary (raw observations, no verdict)
# =====================================================================
Write-Host "[8/8] Parsing combined capture and splitting by file"
$allEvents = Import-Csv -Path $csvPath

# Group ONCE by PID instead of filtering the full event array separately
# for every file -- confirmed the hard way: with 15 files this step took
# nearly 2 minutes (repeated Where-Object scans over the same array,
# O(files x events) instead of O(events)). Group-Object builds a
# PID -> events lookup in one pass; indexing into it per file afterward
# is cheap. Matters more as the file count grows toward the full ~41.
$eventsByPid = $allEvents | Group-Object -Property PID -AsHashTable -AsString

$results = @()
foreach ($run in $runLog) {
    $events = $eventsByPid["$($run.Pid_)"]
    if ($null -eq $events) { $events = @() }
    $results += [PSCustomObject]@{
        path = $run.Path
        exit_code = $run.ExitCode
        event_count = $events.Count
        # Keep only the operations most likely to matter for a human
        # skimming this later -- process/network/registry-write --
        # rather than dumping every single ReadFile/RegQueryValue.
        # NOT a verdict, just noise reduction for readability.
        notable_events = $events | Where-Object {
            $_.Operation -in @("Process Create","TCP Connect","TCP Send",
                "TCP Receive","UDP Send","RegSetValue","RegCreateKey",
                "WriteFile","DeleteFile")
        } | ForEach-Object {
            [PSCustomObject]@{ operation = $_.Operation; path = $_.Path; result = $_.Result }
        }
    }
}

Write-Host ""
Write-Host "=== BATCH RESULTS ($($results.Count) files) ==="
$results | ForEach-Object {
    Write-Host ""
    Write-Host "--- $($_.path) ---"
    Write-Host "  exit_code: $($_.exit_code), total_events: $($_.event_count), notable: $($_.notable_events.Count)"
    $_.notable_events | ForEach-Object {
        Write-Host ("    {0,-16} {1,-50} {2}" -f $_.operation, $_.path, $_.result)
    }
}

$reportPath = Join-Path $WorkDir "batch_report.json"
$results | ConvertTo-Json -Depth 5 | Out-File -FilePath $reportPath -Encoding utf8
Write-Host ""
Write-Host "Full report written to: $reportPath"

exit 0
